<?php
require __DIR__.'/app.php';require_login();$currentRole=current_role();$shopId=(int)$_SESSION['shop_id'];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_roles(['owner','company_manager']);verify_csrf();$branchName=trim((string)($_POST['name']??''));if(!$branchName||mb_strlen($branchName)>160){http_response_code(422);exit('اسم الفرع غير صالح.');}try{$branchStatement=db()->prepare('INSERT INTO branches(shop_id,name) VALUES(?,?)');$branchStatement->execute([$shopId,$branchName]);header('Location: branches.php?saved=1');exit;}catch(PDOException $databaseError){$formError='تعذر إضافة الفرع.';}}
if(in_array($currentRole,['owner','company_manager'],true)){$branchStatement=db()->prepare('SELECT id,name,created_at FROM branches WHERE shop_id=? ORDER BY name');$branchStatement->execute([$shopId]);}else{$branchStatement=db()->prepare('SELECT id,name,created_at FROM branches WHERE shop_id=? AND id=?');$branchStatement->execute([$shopId,(int)($_SESSION['branch_id']??0)]);}$branchRows=$branchStatement->fetchAll();page_start('الفروع');if(isset($_GET['saved']))echo '<p class="success">تمت إضافة الفرع.</p>';if(!empty($formError))echo '<p class="alert">'.e($formError).'</p>';if(in_array($currentRole,['owner','company_manager'],true))echo '<section class="card"><form method="post">'.csrf_field().'<label>اسم الفرع<input name="name" maxlength="160" required></label><button>إضافة فرع</button></form></section>';echo '<section class="card table-wrap"><table><thead><tr><th>الفرع</th><th>تاريخ الإضافة</th></tr></thead><tbody>';foreach($branchRows as $branch)echo '<tr><td>'.e($branch['name']).'</td><td>'.e($branch['created_at']).'</td></tr>';if(!$branchRows)echo '<tr><td colspan="2">لا توجد فروع.</td></tr>';echo '</tbody></table></section>';page_end();

